#!/usr/bin/env bash
# Create .local/dev.env with generated secrets (once). Never committed.
set -euo pipefail
source "$(dirname "$0")/../lib/common.sh"
env_file=$REPO_ROOT/.local/dev.env
mkdir -p "$REPO_ROOT/.local/dev-state/logs" "$REPO_ROOT/.local/dev-state/cache"
if [[ -f $env_file ]]; then
	echo "exists: $env_file"
	exit 0
fi
umask 077
cat >"$env_file" <<ENV
# Generated by scripts/dev/init-env.sh on $(date -u +%Y-%m-%dT%H:%M:%SZ). Local only.
DEV_STATE_DIR=$REPO_ROOT/.local/dev-state
DEV_SITE=erp.localhost
DEV_TEST_SITE=test.localhost
DEV_HTTP_PORT=18000
DEV_SOCKETIO_PORT=19000
DEV_DB_ROOT_PASSWORD=$(random_secret)
DEV_ADMIN_PASSWORD=$(random_secret)
ENV
echo "created: $env_file"
